use core::fmt;

use crate::domain::value::ValueError;

const MIN_CLIENT_ID_LEN: usize = 16;
const MAX_CLIENT_ID_LEN: usize = 64;

/// A public OAuth client identifier.
///
/// Client identifiers are generated by the server, globally unique, and non-sequential.
/// They are not derived from an application slug or a database row ID.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ClientId(String);

impl ClientId {
    /// Parses a public client identifier.
    pub fn parse(value: impl Into<String>) -> Result<Self, ValueError> {
        let value = value.into();

        if value.is_empty() {
            return Err(ValueError::Empty { field: "client_id" });
        }
        if value.len() < MIN_CLIENT_ID_LEN {
            return Err(ValueError::TooShort {
                field: "client_id",
                min: MIN_CLIENT_ID_LEN,
                actual: value.len(),
            });
        }
        if value.len() > MAX_CLIENT_ID_LEN {
            return Err(ValueError::TooLong {
                field: "client_id",
                max: MAX_CLIENT_ID_LEN,
                actual: value.len(),
            });
        }
        if !value.is_ascii() {
            return Err(ValueError::InvalidFormat {
                field: "client_id",
                reason: "must use ASCII characters",
            });
        }
        let mut bytes = value.bytes();
        let first = bytes.next().unwrap_or_default();
        if !first.is_ascii_alphanumeric() {
            return Err(ValueError::InvalidFormat {
                field: "client_id",
                reason: "must start with an ASCII letter or digit",
            });
        }
        if !bytes.all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_')) {
            return Err(ValueError::InvalidFormat {
                field: "client_id",
                reason: "may contain only ASCII letters, digits, hyphens, and underscores",
            });
        }

        Ok(Self(value))
    }

    /// Returns the client identifier.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for ClientId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl AsRef<str> for ClientId {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_url_safe_identifiers() {
        let id = ClientId::parse("abcDEF0123456789-_xyz").expect("valid client id");
        assert_eq!(id.as_str(), "abcDEF0123456789-_xyz");
    }

    #[test]
    fn rejects_short_or_unsafe_identifiers() {
        for value in [
            "short",
            "-abcDEF0123456789",
            "abc DEF0123456789",
            "abc/DEF0123456789",
        ] {
            assert!(
                ClientId::parse(value).is_err(),
                "{value:?} should be rejected"
            );
        }
    }
}
